#!/bin/sh

# test-10032026-Maurice
# test-10042026-Maurice: exact lifecycle migration inventory regression guard.
# Ticket 08 RED contract: approval/reopen lifecycle, immutable approved data,
# lifecycle events/audit visibility, and approved-only reporting.
# Mapped to TC0005/0006/0009/0010/0022/0027-0031.
set -eu
umask 077
MAX_FAILURES=1
REPO_ROOT=$(CDPATH= cd -- "$(dirname -- "$0")/../.." && pwd)
COMPOSE_FILE=$REPO_ROOT/compose.yaml
PROJECT_NAME=${OJT_TEST_COMPOSE_PROJECT:-ojt-ticket08-$$}
APP_PORT=${OJT_TEST_APP_PORT:-$((18300 + ($$ % 600)))}
TMP_ROOT=${TMPDIR:-/tmp}/ojt-ticket08-$$
COMPOSE_STARTED=0
mkdir -p "$TMP_ROOT"
trap 'if [ "$COMPOSE_STARTED" = 1 ]; then docker compose -p "$PROJECT_NAME" -f "$COMPOSE_FILE" down --volumes --remove-orphans >/dev/null 2>&1 || :; fi; rm -rf -- "$TMP_ROOT"' EXIT HUP INT TERM
logger -t ojt-ticket08 "event=startup status=begin test=ticket08_lifecycle_test max_failures=$MAX_FAILURES" || :

# Static gates deliberately precede Docker and provide the initial RED.
logger -t ojt-ticket08 'event=major-operation status=check cases=TC0005,TC0006,TC0009,TC0010,TC0022,TC0027,TC0028,TC0029,TC0030,TC0031 assertion=lifecycle-artifacts' || :
LIFECYCLE_MIGRATION="$REPO_ROOT/database/migrations/2026_10_04_000001_create_internship_lifecycle_events_table.php"
[ -f "$LIFECYCLE_MIGRATION" ] || { printf '%s\n' 'FAIL [TC0005]: exact lifecycle event migration is missing (Docker not started)' >&2; exit 1; }
grep -Eq '^class[[:space:]]+CreateInternshipLifecycleEventsTable[[:space:]]+extends[[:space:]]+Migration' "$LIFECYCLE_MIGRATION" || { printf '%s\n' 'FAIL [TC0005]: lifecycle migration class/schema target is not exact (Docker not started)' >&2; exit 1; }
grep -Eq "Schema::create\('internship_lifecycle_events'|bigIncrements\('id'\)|unsignedInteger\('internship_id'\)|unsignedInteger\('actor_id'\)|string\('event_type', 16\)|boolean\('from_is_approved'\)|boolean\('to_is_approved'\)|string\('reason', 500\)->nullable" "$LIFECYCLE_MIGRATION" || { printf '%s\n' 'FAIL [TC0005]: lifecycle event schema columns are incomplete (Docker not started)' >&2; exit 1; }
grep -Fq "foreign('internship_id')->references('id')->on('internships')->onDelete('restrict')" "$LIFECYCLE_MIGRATION" || { printf '%s\n' 'FAIL [TC0005]: internship lifecycle foreign key is missing (Docker not started)' >&2; exit 1; }
grep -Fq "foreign('actor_id')->references('id')->on('users')->onDelete('restrict')" "$LIFECYCLE_MIGRATION" || { printf '%s\n' 'FAIL [TC0005]: actor lifecycle foreign key is missing (Docker not started)' >&2; exit 1; }
grep -Fq 'CREATE TRIGGER internship_lifecycle_events_before_insert' "$LIFECYCLE_MIGRATION" || { printf '%s\n' 'FAIL [TC0005]: lifecycle insert trigger is missing (Docker not started)' >&2; exit 1; }
grep -Fq 'CREATE TRIGGER internship_lifecycle_events_before_update' "$LIFECYCLE_MIGRATION" || { printf '%s\n' 'FAIL [TC0005]: lifecycle update immutability trigger is missing (Docker not started)' >&2; exit 1; }
grep -Fq 'CREATE TRIGGER internship_lifecycle_events_before_delete' "$LIFECYCLE_MIGRATION" || { printf '%s\n' 'FAIL [TC0005]: lifecycle delete immutability trigger is missing (Docker not started)' >&2; exit 1; }
grep -Fq 'DROP TRIGGER IF EXISTS internship_lifecycle_events_before_insert' "$LIFECYCLE_MIGRATION" || { printf '%s\n' 'FAIL [TC0005]: lifecycle down cleanup is missing (Docker not started)' >&2; exit 1; }
[ -f "$REPO_ROOT/app/InternshipLifecycleEvent.php" ] || { printf '%s\n' 'FAIL [TC0005]: lifecycle event model is missing (Docker not started)' >&2; exit 1; }
grep -Eiq 'approve|reopen' "$REPO_ROOT/routes/api.php" || { printf '%s\n' 'FAIL [TC0006]: approve/reopen routes are missing (Docker not started)' >&2; exit 1; }
grep -Eiq 'events|lifecycle' "$REPO_ROOT/routes/api.php" || { printf '%s\n' 'FAIL [TC0005]: lifecycle event read route is missing (Docker not started)' >&2; exit 1; }
grep -Eiq 'public function approve|public function reopen' "$REPO_ROOT/app/Http/Controllers/InternshipController.php" || { printf '%s\n' 'FAIL [TC0006]: approve/reopen methods are missing (Docker not started)' >&2; exit 1; }
grep -Eiq 'DB::transaction|lockForUpdate' "$REPO_ROOT/app/Services/InternshipLifecycleService.php" || { printf '%s\n' 'FAIL [TC0009]: lifecycle transaction/row locks are missing (Docker not started)' >&2; exit 1; }
grep -Eiq 'audit|lifecycle.?event|event.*create|reason' "$REPO_ROOT/app/Http/Controllers/InternshipController.php" "$REPO_ROOT/app/InternshipLifecycleEvent.php" || { printf '%s\n' 'FAIL [TC0005]: lifecycle audit write is missing (Docker not started)' >&2; exit 1; }
grep -Eiq 'is_approved.*1|where.*is_approved.*1|approved' "$REPO_ROOT/app/Services/InternshipReportingService.php" || { printf '%s\n' 'FAIL [TC0022]: reporting lacks authoritative approved filter (Docker not started)' >&2; exit 1; }
grep -Eiq "internships/report/pdf|report.*pdf" "$REPO_ROOT/routes/api.php" "$REPO_ROOT/app/Http/Controllers/InternshipReportingController.php" || { printf '%s\n' 'FAIL [TC0022]: reporting PDF contract is missing (Docker not started)' >&2; exit 1; }
grep -Eiq 'SessionTracer::enter|SessionTracer::leave|SessionTracer::exception|catch[[:space:]]*\([^)]*Throwable' "$REPO_ROOT/app/Http/Controllers/InternshipController.php" "$REPO_ROOT/app/Services/InternshipReportingService.php" || { printf '%s\n' 'FAIL [TC0031]: lifecycle/reporting trace envelope is missing (Docker not started)' >&2; exit 1; }
[ -f "$COMPOSE_FILE" ] || { printf '%s\n' 'FAIL [TC0031]: compose.yaml is required' >&2; exit 1; }
command -v docker >/dev/null 2>&1 || { printf '%s\n' 'FAIL [TC0031]: docker is required' >&2; exit 1; }
command -v timeout >/dev/null 2>&1 || { printf '%s\n' 'FAIL [TC0031]: timeout is required' >&2; exit 1; }
command -v curl >/dev/null 2>&1 || { printf '%s\n' 'FAIL [TC0031]: curl is required' >&2; exit 1; }
if command -v nc >/dev/null 2>&1 && nc -z 127.0.0.1 "$APP_PORT" >/dev/null 2>&1; then printf '%s\n' 'FAIL [TC0031]: selected app port is already in use' >&2; exit 1; fi

# Container-only Passport probe. Tokens and fixture identities never reach output.
cat >"$TMP_ROOT/lifecycle_probe.php" <<'PHP'
<?php
$base=rtrim(getenv('OJT_PROBE_BASE_URL'),'/');$corr='ticket08-correlation';
$a=App\User::firstOrCreate(['sr_code'=>'T08-A'],['name'=>'Ticket08 A','email'=>'t08-a@example.invalid','password'=>bcrypt('t08-a'),'role'=>'student']);
$b=App\User::firstOrCreate(['sr_code'=>'T08-B'],['name'=>'Ticket08 B','email'=>'t08-b@example.invalid','password'=>bcrypt('t08-b'),'role'=>'student']);
$c=App\User::firstOrCreate(['sr_code'=>'T08-C'],['name'=>'Ticket08 C','email'=>'t08-c@example.invalid','password'=>bcrypt('t08-c'),'role'=>'coordinator']);
